-- Modern Player Motion: loader. Plan and change log: addons/MPMDIDDY/PLAN.md
MPM = MPM or {}

local shared = { "mpm/sh_config.lua", "mpm/sh_state.lua", "mpm/sh_input.lua", "mpm/sh_move.lua" }
local client = { "mpm/cl_debug.lua", "mpm/cl_gun.lua", "mpm/cl_menu.lua" }

-- generated by mpm_build.py (clip speeds / foot plants); optional until anims are built
if file.Exists("mpm/data/clips.lua", "LUA") then
    table.insert(shared, "mpm/data/clips.lua")
    table.insert(shared, "mpm/sh_anim.lua")
    table.insert(shared, "mpm/sh_anim_trans.lua")
    table.insert(shared, "mpm/sh_anim_guns.lua")
end
table.insert(shared, "mpm/sh_animtest.lua")

for _, f in ipairs(shared) do
    if SERVER then AddCSLuaFile(f) end
    include(f)
end

for _, f in ipairs(client) do
    if SERVER then AddCSLuaFile(f) else include(f) end
end
